    console.log("\n[3C.6] Limpando .next/dev antes do TypeScript...");
    fs.rmSync(nextDev, { recursive: true, force: true });
  }

  const npx = process.platform === "win32" ? "npx.cmd" : "npx";
  const npm = process.platform === "win32" ? "npm.cmd" : "npm";

