function numeroSeguro(valor: unknown) {
  const numero = Number(valor ?? 0);
  return Number.isFinite(numero) ? numero : 0;
}

function formatarMoeda(valor: unknown) {
  return numeroSeguro(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

function formatarData(data?: string | null) {
  if (!data) return "-";

  const d = new Date(data);

  if (Number.isNaN(d.getTime())) return "-";

  return d.toLocaleDateString("pt-BR");
}

function formatarDataInput(data: Date) {
  const ano = data.getFullYear();
  const mes = String(data.getMonth() + 1).padStart(2, "0");
  const dia = String(data.getDate()).padStart(2, "0");

  return `${ano}-${mes}-${dia}`;
}

function primeiroDiaMes() {
  const hoje = new Date();
  return formatarDataInput(new Date(hoje.getFullYear(), hoje.getMonth(), 1));
}

function dataHoje() {
  return formatarDataInput(new Date());
}

function formatarNumeroOS(valor?: string | number | null) {
  const numero = Number(valor);

  if (Number.isFinite(numero) && numero > 0) {
    return String(Math.trunc(numero)).padStart(3, "0");
  }

  return "---";
}

function classeStatus(status?: string | null) {
  if (status === "ENTREGUE") return "bg-green-50 text-green-700 ring-green-600/20";
  if (status === "PRONTO") return "bg-blue-50 text-blue-700 ring-blue-600/20";
  if (status === "CANCELADO") return "bg-red-50 text-red-700 ring-red-600/20";
  if (status === "AGUARDANDO_PECA") return "bg-yellow-50 text-yellow-700 ring-yellow-600/20";
  if (status === "EM_REPARO") return "bg-purple-50 text-purple-700 ring-purple-600/20";

  return "bg-slate-100 text-slate-700 ring-slate-600/20";
}

function nomeEquipamento(ordem: OrdemRelatorio) {
  if (ordem.nomeEquipamento) return ordem.nomeEquipamento;

  if (ordem.equipmentType === "OUTRO" && ordem.equipmentOther) {
    return ordem.equipmentOther;
  }

  return nomesEquipamento[ordem.equipmentType || ""] || ordem.equipmentType || "-";
}

function totalEquipamento(item: EquipamentoRelatorio) {
