          id: true,
          osNumber: true,
          customerId: true,
          equipmentType: true,
          equipmentOther: true,
          brand: true,
          model: true,
          status: true,
          technicianUserId: true,
          technicianResponsible: true,
          technicianProfitPercentSnapshot: true,
          totalAmount: true,
          partsCost: true,
          laborCost: true,
          discount: true,
          paidAmount: true,
          openedAt: true,
          technicalParts: {
            select: {
              state: true,
              totalCostSnapshot: true,
            },
          },
          customer: {
            select: {
              id: true,
              name: true,
              whatsapp: true,
            },
          },
        },
