        participacaoTecnicosParcial: financeiroSensivelLiberado
          ? participacaoTecnicosParcial
          : null,
        lucroLoja: financeiroSensivelLiberado ? lucroLoja : null,
        lucroLojaParcial: financeiroSensivelLiberado
          ? lucroLojaParcial
          : null,
        ordensSemParticipacaoCalculavel: financeiroSensivelLiberado
          ? ordensSemParticipacaoCalculavel
          : null,
      },
      ...(financeiroSensivelLiberado ? { tecnicosFinanceiros } : {}),
      equipamentos,
      equipamentosMaisConsertados: equipamentos,
      clientes: clientesMaisAtivos,
      clientesMaisAtivos,
      diagnostico: {
        diaSemanaMaisForte,
        diaSemanaMaisFraco,
        diaMesMaisForte,
        diaMesMaisFraco,
      },
      diasSemana,
      diasPeriodo,
      ordens: ordensFormatadas,
    });
  } catch (error) {
    console.error("Erro ao gerar relatório:", error);

    return NextResponse.json(
      { message: "Erro ao gerar relatório." },
      { status: 500 }
    );
  }
